import { randomPassword } from '../utils/random'

export type Student = {
  id: string
  rollNo: number
  name: string
  gender: 'Male' | 'Female'
  dob: string
  parent: string
  phone: string
  joiningDate: string
  /** Login for the exam page, generated by the admin panel. */
  username: string
  /** Auto-generated. Stored as plain text so the admin can hand it out (demo only — hash it on a real backend). */
  password: string
}


/** e.g. "aarav.lkg.01" — unique because roll numbers are unique within a class. */
export const makeUsername = (name: string, classId: string, rollNo: number) => {
  const first = name.trim().split(/\s+/)[0].toLowerCase().replace(/[^a-z0-9]/g, '') || 'student'
  return `${first}.${classId}.${String(rollNo).padStart(2, '0')}`
}

export const makePassword = () => randomPassword(8)

/** Fills in a username/password for students saved before logins existed. */
export const withCredentials = (byClass: Record<string, Student[]>): Record<string, Student[]> =>
  Object.fromEntries(
    Object.entries(byClass).map(([classId, list]) => [
      classId,
      list.map((s) =>
        s.username && s.password
          ? s
          : {
              ...s,
              username: s.username || makeUsername(s.name, classId, s.rollNo),
              password: s.password || makePassword(),
            },
      ),
    ]),
  )

export type NewStudent = Omit<Student, 'id' | 'rollNo' | 'username' | 'password'>
